import { toDateOnlyString } from "./dates.js";

/** POLA_2 weekend standby marker generated by solver (not a human manual edit). */
export const STANDBY_HIGHLIGHT = "#bfdbfe";
export const STANDBY_NOTE = "S2 cadangan weekend (bisa dipindah isi jadwal kosong)";

/**
 * Determine whether a ShiftSchedule cell carries human/manual edits that must
 * be preserved during safe schedule generation (`preserve_manual`).
 */
export function isManuallyProtectedCell(cell) {
  if (!cell) return false;
  if (cell.manualEdited === true) return true;
  if (cell.isLembur === true) return true;
  if (cell.noteUpdatedBy != null) return true;

  const trimmedNote = typeof cell.note === "string" ? cell.note.trim() : "";
  const isStandbyAutoNote = trimmedNote === STANDBY_NOTE;
  if (trimmedNote.length > 0 && !isStandbyAutoNote) return true;

  const hl = typeof cell.highlightColor === "string" ? cell.highlightColor.trim().toLowerCase() : "";
  if (hl.length > 0 && !(isStandbyAutoNote && hl === STANDBY_HIGHLIGHT)) {
    return true;
  }

  if (
    cell.generatedShiftTypeId !== undefined &&
    cell.generatedShiftTypeId !== null &&
    cell.shiftTypeId !== cell.generatedShiftTypeId
  ) {
    return true;
  }

  return false;
}

/**
 * Partition existing month rows vs newly generated solver rows.
 * - `preserve_manual` (default): keeps manually edited/annotated/lembur cells intact,
 *   replaces unedited generated rows, and clears unedited rows belonging to users
 *   no longer in the eligible pool (e.g. resigned/non-shift).
 * - `force_all`: removes all existing rows in the department month and writes all generated rows.
 */
export function partitionDepartmentMonthRows({
  existingRows = [],
  generatedRows = [],
  overwriteMode = "preserve_manual",
}) {
  const mode = overwriteMode === "force_all" ? "force_all" : "preserve_manual";
  const makeKey = (userId, date) => `${userId}::${toDateOnlyString(date) || ""}`;

  if (mode === "force_all") {
    return {
      overwriteMode: mode,
      deleteIds: existingRows.map((r) => r.id).filter((id) => id != null),
      creates: generatedRows,
      preservedCount: 0,
      deletedCount: existingRows.length,
      createdCount: generatedRows.length,
    };
  }

  const protectedKeys = new Set();
  const deleteIds = [];
  let preservedCount = 0;

  for (const row of existingRows) {
    const key = makeKey(row.userId, row.date);
    if (isManuallyProtectedCell(row)) {
      protectedKeys.add(key);
      preservedCount++;
    } else if (row.id != null) {
      deleteIds.push(row.id);
    }
  }

  const creates = generatedRows.filter((row) => {
    const key = makeKey(row.userId, row.date);
    return !protectedKeys.has(key);
  });

  return {
    overwriteMode: mode,
    deleteIds,
    creates,
    preservedCount,
    deletedCount: deleteIds.length,
    createdCount: creates.length,
  };
}

/**
 * Whether a user belongs to the active shift-solver roster pool.
 */
export function isRosterEligibleUser(user) {
  if (!user) return false;
  if (user.active === false) return false;
  if (user.scheduleEligible === false) return false;
  if (user.role?.name === "Manager") return false;
  if (String(user.email || "").trim().length === 0) return false;
  return true;
}

/**
 * Structured roster eligibility classification for Team & Schedule UI badges.
 * @returns {{ eligible: boolean, code: 'eligible'|'resigned'|'non_shift_manager'|'non_shift_manual'|'no_email', label: string }}
 */
export function getRosterStatus(user) {
  if (!user || user.active === false) {
    return { eligible: false, code: "resigned", label: "Resign / Nonaktif" };
  }
  if (user.role?.name === "Manager") {
    return { eligible: false, code: "non_shift_manager", label: "Non-Shift (Manager)" };
  }
  if (user.scheduleEligible === false) {
    return { eligible: false, code: "non_shift_manual", label: "Non-Shift" };
  }
  if (String(user.email || "").trim().length === 0) {
    return { eligible: false, code: "no_email", label: "Email Kosong" };
  }
  return { eligible: true, code: "eligible", label: "Aktif Shift" };
}

/**
 * Whether an auto-generate run key represents a completed month (all enabled depts ok or safely skipped).
 */
export function isAutoGenerateRunComplete(results = []) {
  return Array.isArray(results) && !results.some((r) => r.ok === false);
}
